const BY_ID: ReadonlyMap<string, StickerDef> = new Map(STICKERS.map((sticker) => [sticker.id, sticker]));

export function stickerById(id: string | null | undefined): StickerDef | null {
  return id == null ? null : (BY_ID.get(id) ?? null);
}
